#!/usr/bin/env node
// Packed consumers (M8): example pages served from tarballs installed outside the workspace. Each
// consumer installs only the packages it needs; its import map is generated by walking the
// installed modules through each package's `exports` (default, production conditions); its
// stylesheets must be published files; its CSP hash is recomputed. Run after `npm run build`.
//
//   node scripts/packed-consumers.mjs --port 4174
//   node scripts/packed-consumers.mjs --import-map examples/full-app   (prints the workspace map)
//
// Serves /<consumer>/ for each consumer below; packing starts on the first request for it, and
// /<consumer>/__ready reports the installed packages, the import map, and every module file the
// page loads (e2e/packed-consumers.spec.ts, e2e/components-only.spec.ts).
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { createServer } from 'node:http';
import { cp, mkdir, readFile, realpath, rm, stat, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, extname, join, normalize, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { init, parse } from 'es-module-lexer';

const root = resolve(fileURLToPath(new URL('..', import.meta.url)));

/** Each consumer: the packages it installs, the example page, and the files copied from it. */
export const CONSUMERS = {
  'css-only': {
    packages: ['tokens'],
    page: 'examples/tokens-css-only',
    files: ['index.html', 'styles.css', 'theme.json'],
    // The CSS-only path: the installed CLI generates the stylesheet the page links.
    generate: ['build', 'theme.json', '--out', 'generated', '--format', 'css', '--strict'],
  },
  'core-only': {
    packages: ['core'],
    page: 'examples/core-counter',
    files: ['index.html', 'styles.css', 'dist'],
  },
  'components-only': {
    packages: ['core', 'tokens', 'components'],
    page: 'examples/components-only',
    files: ['index.html', 'main.js', 'styles.css'],
  },
  'full-app': {
    packages: ['core', 'tokens', 'components', 'state', 'app'],
    page: 'examples/full-app',
    files: ['index.html', 'main.js', 'styles.css'],
  },
};

const npmCli = process.env['npm_execpath']?.endsWith('.js')
  ? process.env['npm_execpath']
  : join(dirname(process.execPath), 'node_modules', 'npm', 'bin', 'npm-cli.js');
const run = (args, cwd) =>
  execFileSync(process.execPath, args, {
    cwd,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });
const npm = (args, cwd) => run([npmCli, ...args], cwd);

const exported = (manifest, subpath, condition) => {
  const target = manifest.exports?.[subpath];
  return typeof target === 'string' ? target : (target?.[condition] ?? target?.default);
};

/** The file a bare specifier resolves to through the package's `exports` under `modules`. */
async function resolveSpecifier(modules, specifier, condition) {
  const match = /^(@[^/]+\/[^/]+)(?:\/(.+))?$/.exec(specifier);
  if (!match) throw new Error(`${specifier}: not a scoped package`);
  const dir = await realpath(join(modules, ...match[1].split('/')));
  const manifest = JSON.parse(await readFile(join(dir, 'package.json'), 'utf8'));
  const path = exported(manifest, match[2] ? `./${match[2]}` : '.', condition);
  if (!path) throw new Error(`${specifier}: not exported by ${match[1]}`);
  return join(dir, path);
}

const urlFrom = (from, file) => {
  const path = relative(from, file).split(sep).join('/');
  return path.startsWith('.') ? path : `./${path}`;
};

/** The module scripts an HTML page loads, as files. */
const moduleScripts = (html, dir) =>
  [...html.matchAll(/<script type="module" src="([^"]+)"/g)].map(([, src]) => resolve(dir, src));

/**
 * The import map for everything reachable from `entries` (bare specifiers resolved under
 * `modules` with `condition`), with URLs relative to `pageDir`, and every module file visited.
 */
export async function importMap(entries, { modules, pageDir, condition = 'default' }) {
  await init;
  const imports = {};
  const files = new Set();
  const visit = async (file) => {
    if (files.has(file)) return;
    files.add(file);
    const [records] = parse(await readFile(file, 'utf8'));
    for (const { specifier } of records) {
      if (!specifier) continue;
      if (specifier.startsWith('.')) {
        await visit(resolve(dirname(file), specifier));
        continue;
      }
      const target = await resolveSpecifier(modules, specifier, condition);
      imports[specifier] = urlFrom(pageDir, target);
      await visit(target);
    }
  };
  for (const entry of entries) await visit(entry);
  return {
    imports: Object.fromEntries(Object.entries(imports).sort(([a], [b]) => a.localeCompare(b))),
    files: [...files].map((file) => urlFrom(pageDir, file)).sort(),
  };
}

/** A workspace path such as ../../packages/tokens/dist/css/default.css as its published file. */
async function publishedFile(site, path) {
  const [, name, file] = /^\.\.\/\.\.\/packages\/([^/]+)\/(.+)$/.exec(path) ?? [];
  if (!name) return path;
  const dir = join(site, 'node_modules', '@oddkin', name);
  const manifest = JSON.parse(await readFile(join(dir, 'package.json'), 'utf8'));
  const published = Object.keys(manifest.exports ?? {}).some(
    (key) => exported(manifest, key, 'default') === `./${file}`,
  );
  if (!published) throw new Error(`${path}: not a published file of @oddkin/${name}`);
  return urlFrom(site, join(dir, file));
}

/** Rewrite a page's import map (and the CSP hash of that inline script) to `imports`. */
function withImportMap(html, imports) {
  if (!/<script type="importmap">/.test(html)) return html;
  const map = `\n${JSON.stringify({ imports }, null, 2)}\n`;
  const hash = createHash('sha256').update(map).digest('base64');
  return html
    .replace(/(<script type="importmap">)[\s\S]*?(<\/script>)/, `$1${map}$2`)
    .replace(/'sha256-[^']+'/, `'sha256-${hash}'`);
}

const tarballs = new Map();
/** Pack each workspace package once per process. */
function pack(name, work) {
  if (!tarballs.has(name)) {
    const [info] = JSON.parse(
      npm(['pack', '--json', '--pack-destination', work], join(root, 'packages', name)),
    );
    tarballs.set(name, join(work, info.filename));
  }
  return tarballs.get(name);
}

/**
 * Pack, install, and copy the consumer's page into `work/<name>` (emptied first). Returns the
 * site directory, the installed packages, the import map, and every module file the page loads.
 */
export async function packConsumer(name, work) {
  const consumer = CONSUMERS[name];
  if (!consumer) throw new Error(`Unknown consumer ${name}`);
  await mkdir(join(work, 'tarballs'), { recursive: true });
  const site = join(work, name);
  await rm(site, { recursive: true, force: true });
  await mkdir(site, { recursive: true });
  await writeFile(
    join(site, 'package.json'),
    JSON.stringify({ name: `${name}-consumer`, private: true, type: 'module' }),
  );
  const files = consumer.packages.map((pkg) => pack(pkg, join(work, 'tarballs')));
  npm(['install', '--no-audit', '--no-fund', '--ignore-scripts', ...files], site);
  const installed = new Set();
  const walk = (deps = {}) => {
    for (const [dep, info] of Object.entries(deps)) {
      installed.add(dep);
      walk(info.dependencies);
    }
  };
  walk(JSON.parse(npm(['ls', '--all', '--json'], site)).dependencies);

  const pageDir = join(root, consumer.page);
  for (const file of consumer.files)
    await cp(join(pageDir, file), join(site, file), {
      recursive: true,
      filter: (source) => !/\.(map|tsbuildinfo)$|\.d\.ts$/.test(source),
    });
  if (consumer.generate) {
    const manifest = JSON.parse(
      await readFile(join(site, 'node_modules/@oddkin/tokens/package.json'), 'utf8'),
    );
    const bin = join(site, 'node_modules/@oddkin/tokens', Object.values(manifest.bin)[0]);
    run([bin, ...consumer.generate], site);
  }
  let html = await readFile(join(site, 'index.html'), 'utf8');
  const map = await importMap(moduleScripts(html, site), {
    modules: join(site, 'node_modules'),
    pageDir: site,
  });
  html = withImportMap(html, map.imports);
  for (const [, href] of html.matchAll(/href="([^"]+)"/g))
    html = html.replace(`href="${href}"`, `href="${await publishedFile(site, href)}"`);
  if (html.includes('../../'))
    throw new Error(`${name}: index.html still references the workspace`);
  await writeFile(join(site, 'index.html'), html);
  return { site, installed: [...installed].sort(), ...map };
}

const types = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
};

function serve(port) {
  // One directory per port: a server stopped without cleanup (Windows) leaves at most one copy.
  const work = join(tmpdir(), `oddkin-packed-consumers-${port}`);
  const packed = new Map();
  const ready = (name) => {
    if (!packed.has(name)) packed.set(name, packConsumer(name, work));
    return packed.get(name);
  };
  const server = createServer(async (request, response) => {
    const url = new URL(request.url ?? '/', 'http://localhost');
    if (url.pathname === '/__health') return void response.writeHead(200).end('ok');
    const [, name, rest = ''] = /^\/([^/]+)(\/.*)?$/.exec(url.pathname) ?? [];
    if (!name || !CONSUMERS[name]) return void response.writeHead(404).end('Not found');
    if (!rest) return void response.writeHead(301, { location: `/${name}/` }).end();
    let consumer;
    try {
      consumer = await ready(name);
    } catch (error) {
      packed.delete(name);
      return void response.writeHead(500).end(String(error.stderr || error.message || error));
    }
    if (rest === '/__ready') {
      const { installed, imports, files } = consumer;
      response.writeHead(200, { 'content-type': types['.json'] });
      return void response.end(JSON.stringify({ installed, imports, files }));
    }
    let path = normalize(join(consumer.site, decodeURIComponent(rest)));
    if (path !== consumer.site && !path.startsWith(consumer.site + sep))
      return void response.writeHead(403).end('Forbidden');
    try {
      if ((await stat(path)).isDirectory()) path = join(path, 'index.html');
      const body = await readFile(path);
      response.writeHead(200, {
        'content-type': types[extname(path)] ?? 'application/octet-stream',
      });
      response.end(body);
    } catch {
      response.writeHead(404).end('Not found');
    }
  });
  const stop = () => {
    server.close();
    rm(work, { recursive: true, force: true }).finally(() => process.exit(0));
  };
  process.on('SIGINT', stop);
  process.on('SIGTERM', stop);
  server.listen(port, '127.0.0.1', () =>
    console.log(
      `Packed consumers at http://127.0.0.1:${port}/<${Object.keys(CONSUMERS).join('|')}>/`,
    ),
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const arg = (flag) => {
    const i = process.argv.indexOf(flag);
    return i > -1 ? process.argv[i + 1] : undefined;
  };
  const page = arg('--import-map');
  if (page) {
    // The workspace import map of a page (development builds), for its index.html.
    const pageDir = resolve(root, page);
    const html = await readFile(join(pageDir, 'index.html'), 'utf8');
    const { imports } = await importMap(moduleScripts(html, pageDir), {
      modules: join(root, 'node_modules'),
      pageDir,
      condition: 'development',
    });
    console.log(JSON.stringify({ imports }, null, 2));
  } else serve(Number(arg('--port') ?? 4174));
}
